#include "packed_weights.h"
#include <iostream>
int main(){using namespace hip_reference;for(unsigned c:{64u,128u}){size_t cc=size_t(c)*c;std::vector<float>v(9*cc+c,.1234567f);auto*b=(uint8_t*)v.data();for(auto r:std::vector<std::pair<size_t,size_t>>{{0,4*cc},{16*cc,4*cc},{32*cc,cc}})for(size_t i=0;i<r.second;i++)b[r.first+i]=uint8_t(i*37+i/256);auto old=v;AppendWaveW16Half(v,c);if(std::memcmp(old.data(),v.data(),old.size()*4))return 1;auto*h=(uint16_t*)((uint8_t*)v.data()+old.size()*4);size_t n=0;for(auto r:std::vector<std::pair<size_t,size_t>>{{0,4*cc},{16*cc,4*cc},{32*cc,cc}})for(size_t i=0;i<r.second;i++)if(h[n++]!=AmpereFp8HalfBits(((uint8_t*)old.data())[r.first+i]))return 2;std::cout<<"C="<<c<<" old="<<old.size()*4<<" new="<<v.size()*4<<" half="<<n<<" old_prefix_unchanged=1\n";}return 0;}
